(async()=>{const out={};async function run(configure){const c=new OfflineAudioContext(1,16,8000),s=c.createBufferSource(),g=c.createGain(),b=c.createBuffer(1,16,8000);b.getChannelData(0).fill(1);s.buffer=b;s.connect(g);g.connect(c.destination);configure(g.gain);s.start();return Array.from((await c.startRendering()).getChannelData(0))}out.implicitMutation=await run(p=>{p.linearRampToValueAtTime(0,8/8000);p.value=2});out.implicitCancel=await run(p=>{p.linearRampToValueAtTime(0,8/8000);p.value=2;p.cancelScheduledValues(4/8000)});out.sign=await run(p=>p.exponentialRampToValueAtTime(-1,8/8000));out.negative=await run(p=>p.setValueAtTime(-1,0).exponentialRampToValueAtTime(-.25,8/8000));out.curveEndCancel=await run(p=>p.setValueCurveAtTime([0,1],0,8/8000).cancelScheduledValues(8/8000));return out})()
